# =====================================================================================================================
# 0.2.4 THE MODIFIER SLOTS (read side; plain java.lang through skyy.bridge, never throws)
# =====================================================================================================================
# the loadout's 8 modifier picks (row * 2 + slot) as the cells show them: own picks, else the saved snapshot's modifiers of its four
# abilities, else all Keep (null)
M(brg, r"""
public static String[] modsOf(@PKG@.WdLoad L) {
  String[] r = new String[8];
  if (L.abOwn) {
    for (int i = 0; i < 8; i++) r[i] = L.am != null && i < L.am.length ? L.am[i] : null;
    return r;
  }
  if (L.abil == null) return r;
  String[] sr = snapRows(L.abil);
  for (int k = 0; k < 4; k++) {
    String[] m = @PKG@.WdLoad.snapMods(L.abil, sr[k]);
    if (m != null) { r[k * 2] = m[0]; r[k * 2 + 1] = m[1]; }
  }
  return r;
}""")
# class:fn:abilMods {UUID, abilityId} -> String[] (SkyyClasses 0.1.22+): [0] = "id|name|lvl|uses|lvText|noun|slots|eq0|eq1|...", then one row
# per offered modifier "mid|name|at|unlocked(1/0)|level|uses|next|count|stack|now text|next text|doubles(1/0)|max"; null = no bridge /
# not that profile's ability
M(brg, r"""
public static String[] modsRaw(java.util.UUID u, String aid) {
  if (u == null || aid == null || aid.length() == 0) return null;
  java.util.function.Function f = @PKG@.WdLog.fn("class:fn:abilMods");
  if (f == null) return null;
  MODS_CALLS = MODS_CALLS + 1L;
  try {
    Object r = f.apply(new Object[] { u, aid });
    if (r instanceof String[] && ((String[]) r).length > 0 && ((String[]) r)[0] != null) return (String[]) r;
  } catch (Throwable t) { @PKG@.WdLog.warnOnce("abilmods", "class:fn:abilMods failed (the modifier slots hide): " + t); }
  return null;
}""")
M(brg, "public static boolean modsHas() { return @PKG@.WdLog.fn(\"class:fn:abilMods\") != null; }")
# the head: { open slots, live modifier 1, live modifier 2 } ("" = empty)
M(brg, r"""
public static String[] modHead(String[] raw) {
  String[] h = new String[] { "0", "", "" };
  if (raw == null || raw.length == 0 || raw[0] == null) return h;
  String[] p = raw[0].split("\\|", -1);
  if (p.length > 8) { h[0] = p[6].trim(); h[1] = p[7].trim(); h[2] = p[8].trim(); }
  return h;
}""")
M(brg, r"""
public static int modSlots(String[] raw) {
  try { return Integer.parseInt(modHead(raw)[0]); } catch (Throwable t) { return 0; }
}""")
# one offered modifier row split (>= 12 fields), or null
M(brg, r"""
public static String[] modRow(String[] raw, String mid) {
  if (raw == null || mid == null || mid.length() == 0) return null;
  for (int j = 1; j < raw.length; j++) {
    if (raw[j] == null) continue;
    String[] p = raw[j].split("\\|", -1);
    if (p.length >= 12 && p[0].trim().equalsIgnoreCase(mid)) return p;
  }
  return null;
}""")
M(brg, r"""
public static String modName(String[] raw, String mid) {
  if (mid == null || mid.length() == 0) return "Empty";
  String[] p = modRow(raw, mid);
  return p != null && p[1].length() > 0 ? p[1] : abName(mid);
}""")
# the Lattice's placeholder icon of a modifier (SkyyTrees' MOD_ICON), "" = none
M(brg, r"""
public static String modIcon(String mid) {
  if (mid == null) return "";
  for (int i = 0; i < MODID.length; i++) if (MODID[i].equalsIgnoreCase(mid)) return MODIC[i];
  return "";
}""")
M(brg, r"""
public static String abNm(Object[] st, String id) {
  int j = rowOf(st, id);
  return j >= 0 ? ((String[]) st[2])[j] : abName(id);
}""")
