# shows my old crude hatchet after i upgraded to copper. and its not letting me put my hoe in the items. but it allows the other tools."
# BUG 2 - THE HOE: vanilla Tool_Hoe_* items have no Tool and no Weapon block (Assets.zip: they till through Interactions), so classify() fell
# through to "Blocks and materials". Every one-per-stack Tool_* item (every tier: Crude Copper Iron Thorium ...), SkyyFishing's rods and any
# item carrying SkyyGear's lifelong mark (document ll = 1) now go to the Items space.
rep('''  if (@PKG@.WdCfg.allow(id)) return "i";''', '''  if (@PKG@.WdCfg.allow(id)) return "i";
  if ((id.startsWith("Tool_") || id.startsWith("SkyyFishing_Rod_")) && @PKG@.WdCodec.maxStack(id) <= 1) return "i";   // 0.2.4: the hoe (no Tool block) + every tool tier
  if (@PKG@.WdCodec.lu(s).length() > 0) return "i";   // 0.2.4: a SkyyGear lifelong tool, whatever its item''')
# BUG 1 - THE OLD-TIER GHOST. SkyyGear's Anvil tier-up (GearUp.upgrade) builds the new item with GearData.carry, which keeps every other
# metadata key - the SkyyRequip stamp included - so a stamped lifelong tool that tiers up stays the same Requip entry (findStamp matches the
# stamp, never the id). What was missing: (a) the entry's display copy kept the OLD id / level until the next deposit, and (b) an entry left
# behind by an old tool (a /pickaxe-style copy, a re-made tool, or - Skyy's requip.log - a plain Crude hatchet put in Requip after the
# upgrade and then gone) stays "NOT WITH YOU" next to the real one. Now each entry remembers SkyyGear's lifelong uid ("lu" in its display
# copy) and WdOps.tidyLL (run by ensure(): every page build and every Requip change, world thread, the live inventory):
#   - refreshes the display copy of every stamped entry you carry (a tier-up shows the new tier at once);
#   - a GHOST = an OUT entry NOT with you while another entry of the SAME lifelong uid is present (IN Requip or stamped on you) -> every
#     loadout pick of the ghost moves to the present entry (a slot of a loadout that already holds it becomes Keep) and the ghost record
#     is forgotten (targets: the LOWEST eid of the present ones - deterministic);
#   - ONE-TIME PASS per profile (run-once marker "llDone" in index.json; absent in 0.2.3 files): on the entries that exist when the marker is
#     first absent, an OUT, not-with-you PLAIN tool record (no SkyyGear document) of a lifelong family (pickaxe / hatchet / hoe / sickle /
#     pole) while that family's lifelong tool is present merges the same way (Skyy's 'Hatchet Crude'). Before it changes anything the
#     profile's files are copied to Skyy_SkyyWardrobe/history/requip-lltidy-<key>-<ms>/ (sizes verified; a failed copy = nothing runs, the
#     marker stays absent) and the requip.log line LIFELONG-ONCE names every record, every moved pick and the Undo (copy the History files
#     back with the server stopped); the marker is set in the same save (a failed save restores everything, marker included). Nothing to
#     merge = the marker is set in memory and written by the next save (no extra write); a profile born under 0.2.4 starts with it. Never again after the marker - a plain tool deposited
#     later is never merged.
#   Only RECORDS go: an entry IN Requip or on you is never touched, no item moves; a forgotten record's item that turns up again is simply
#   deposited as a new entry (as Forget). Logged (LIFELONG-TIDY / LIFELONG-ONCE) + saved; a failed save restores everything.
rep('''"public int shard;", "public org.bson.BsonDocument raw;"):''', '''"public int shard;", "public org.bson.BsonDocument raw;",
           "public String lu;"):   # 0.2.4: SkyyGear's lifelong uid of the item ("" = none)''')
rep('''this.shard = -1; this.raw = null;''', '''this.shard = -1; this.raw = null; this.lu = "";''')
rep('''c.shard = this.shard; c.raw = this.raw;''', '''c.shard = this.shard; c.raw = this.raw; c.lu = this.lu;''')
rep('''this.lv = @PKG@.WdCodec.lv(s);''', '''this.lv = @PKG@.WdCodec.lv(s);
  this.lu = @PKG@.WdCodec.lu(s);   // 0.2.4''')
rep('''sh.put("lv", new org.bson.BsonInt32(this.lv));''', '''sh.put("lv", new org.bson.BsonInt32(this.lv));
  if (this.lu != null && this.lu.length() > 0) sh.put("lu", new org.bson.BsonString(this.lu));   // 0.2.4 (0.2.3 ignores it)''')
rep('''e.lv = @PKG@.WdCodec.intOf(sh, "lv", -1);''', '''e.lv = @PKG@.WdCodec.intOf(sh, "lv", -1);
    String lu0 = @PKG@.WdCodec.strOf(sh, "lu");
    e.lu = lu0 == null ? "" : lu0;''')
rep('''M(cod, r"""
public static boolean unid(@IS@ s) {''', '''# 0.2.4: SkyyGear's lifelong uid (document ll = 1, lu) of a stack, "" = not a lifelong tool
M(cod, r"""
public static String lu(@IS@ s) {
  org.bson.BsonDocument g = gearDoc(s);
  if (g == null || intOf(g, "ll", 0) != 1) return "";
  String u = strOf(g, "lu");
  return u == null ? "" : u.trim();
}""")
# 0.2.4: the lifelong family of an item id: 0 pickaxe, 1 hatchet, 2 hoe, 3 sickle, 4 fishing pole, -1 none (SkyyGear's GearLL kinds)
M(cod, r"""
public static int llFam(String id) {
  if (id == null) return -1;
  if (id.startsWith("Tool_Pickaxe_")) return 0;
  if (id.startsWith("Tool_Hatchet_")) return 1;
  if (id.startsWith("Tool_Hoe_")) return 2;
  if (id.startsWith("Tool_Sickle_")) return 3;
  if (id.startsWith("SkyyFishing_Rod_")) return 4;
  return -1;
}""")
M(cod, r"""
public static boolean unid(@IS@ s) {''')
rep('''# migration (once) + the crash repair of this profile, before anything else.''', '''F(ops, "public static volatile long TIDIED = 0L;")   # harness: ghost records forgotten by tidyLL
F(ops, "public static volatile long ONCE_RUNS = 0L;")   # harness: one-time plain-tool passes that ran (marker absent -> set)
# 0.2.4: copy the profile's Requip files into Skyy_SkyyWardrobe/history/requip-lltidy-<key>-<ms>/ (every file, sizes verified) before the
# one-time pass changes anything; the path, or null = the copy failed (then nothing runs and the marker stays absent for the next try)
M(ops, r"""
public static String llHist(@PKG@.WdData d) {
  try {
    if (@PKG@.WdStore.ROOT == null || @PKG@.WdStore.RQ == null) return null;
    java.nio.file.Path src = @PKG@.WdStore.dirOf(d.key);
    java.nio.file.Path dst = @PKG@.WdStore.ROOT.resolve("history").resolve("requip-lltidy-" + d.key + "-" + System.currentTimeMillis());
    java.nio.file.Files.createDirectories(dst, new java.nio.file.attribute.FileAttribute[0]);
    java.io.File[] fs = src.toFile().listFiles();
    if (fs == null) return null;
    for (int i = 0; i < fs.length; i++) {
      if (!fs[i].isFile()) continue;
      java.nio.file.Path t = dst.resolve(fs[i].getName());
      java.nio.file.Files.copy(fs[i].toPath(), t, new java.nio.file.CopyOption[] { java.nio.file.StandardCopyOption.REPLACE_EXISTING });
      if (java.nio.file.Files.size(t) != fs[i].length()) return null;
    }
    return dst.toString();
  } catch (Throwable t) { @PKG@.WdLog.warnOnce("llhist:" + d.key, "Requip " + d.key + ": the History copy before the one-time tool tidy failed (nothing changed): " + t); return null; }
}""")
# 0.2.4: merge ghost records gh[i] -> to[i] (loadout picks move; a slot of a loadout that already holds the target becomes Keep; the records
# go), saved; a failed save restores everything (once = the one-time pass: the marker is set in the same save and reset on failure)
M(ops, r"""
public static boolean llMerge(@PKG@.WdData d, java.util.ArrayList gh, java.util.ArrayList to, boolean once, String tag, String extra) {
  java.util.HashMap snap = d.snapshot(gh);
  String[] old = new String[d.slots.length * 13];
  StringBuilder lg = new StringBuilder();
  for (int i = 0; i < d.slots.length; i++) {
    @PKG@.WdLoad L = d.slots[i];
    for (int k = 0; k < 13; k++) old[i * 13 + k] = L.picks[k];
    for (int k = 0; k < 13; k++) {
      int g = gh.indexOf(@PKG@.WdLoad.eidOf(L.picks[k]));
      if (g < 0 || @PKG@.WdLoad.type(L.picks[k]) != 2) continue;
      String t = (String) to.get(g);
      boolean dup = false;
      for (int q = 0; q < 13; q++) if (q != k && t.equals(@PKG@.WdLoad.eidOf(L.picks[q]))) dup = true;
      lg.append(" L").append(i + 1).append('.').append(@PKG@.WdClass.slotName(k).replace(' ', '-')).append(':').append(L.picks[k]).append(dup ? "=keep" : "=e:" + t);
      L.picks[k] = dup ? null : "e:" + t;
    }
  }
  StringBuilder gn = new StringBuilder();
  for (int g = 0; g < gh.size(); g++) {
    @PKG@.WdEntry e = d.entry((String) gh.get(g));
    gn.append(' ').append((String) gh.get(g)).append('(').append(e == null ? "?" : e.itemId()).append(")->").append((String) to.get(g));
    d.remove((String) gh.get(g));
  }
  boolean was = d.llDone;
  if (once) d.llDone = true;
  d.loDirty = true;
  if (!@PKG@.WdStore.save(d)) {
    d.restore(snap);
    for (int i = 0; i < d.slots.length; i++) for (int k = 0; k < 13; k++) d.slots[i].picks[k] = old[i * 13 + k];
    d.llDone = was;
    @PKG@.WdLog.warnOnce("tidy:" + d.key, "Requip " + d.key + ": an old lifelong tool record could not be tidied (save failed) - left as it was");
    return false;
  }
  TIDIED = TIDIED + (long) gh.size();
  @PKG@.WdStore.log(tag + " " + d.uuid + " " + d.key + gn.toString() + (lg.length() > 0 ? " picks:" + lg.toString() : "") + extra);
  return true;
}""")
M(ops, r"""
public static int tidyLL(@PKG@.WdData d, @IC@[] cs) {
  if (d == null || d.bad || cs == null || cs.length < 4 || cs[0] == null || cs[1] == null || cs[2] == null) return 0;
  java.util.HashMap live = @PKG@.WdInv.stamps(cs);
  boolean showCh = false;
  java.util.Iterator it = live.keySet().iterator();
  while (it.hasNext()) {   // the display copy follows the item you carry (a tier-up shows its new tier at once)
    String eid = (String) it.next();
    @PKG@.WdEntry e = d.entry(eid);
    @IS@ x = (@IS@) live.get(eid);
    if (e == null || e.kind || e.in || x == null) continue;
    String nl = @PKG@.WdCodec.lu(x);
    if (!x.getItemId().equals(e.sid) || !nl.equals(e.lu) || e.lv != @PKG@.WdCodec.lv(x) || !@PKG@.WdCodec.rar(x).equals(e.rar)) { e.setShow(x); d.touch(e); showCh = true; }
  }
  // the PRESENT lifelong tools (IN Requip or stamped on you): lifelong uid -> eid, family -> eid; the LOWEST eid wins (deterministic)
  java.util.HashMap keep = new java.util.HashMap();
  java.util.HashMap fam = new java.util.HashMap();
  it = d.entries.values().iterator();
  while (it.hasNext()) {
    @PKG@.WdEntry e = (@PKG@.WdEntry) it.next();
    if (e.kind || e.raw != null || !(e.in || live.containsKey(e.eid))) continue;
    String lu = "";
    if (e.in && e.stack != null) lu = @PKG@.WdCodec.lu(e.stack);
    else if (e.lu != null) lu = e.lu;
    if (lu.length() == 0) continue;
    String k0 = (String) keep.get(lu);
    if (k0 == null || e.eid.compareTo(k0) < 0) keep.put(lu, e.eid);
    int fi = @PKG@.WdCodec.llFam(e.itemId());
    if (fi < 0) continue;
    String fk = "f" + fi;
    String f0 = (String) fam.get(fk);
    if (f0 == null || e.eid.compareTo(f0) < 0) fam.put(fk, e.eid);
  }
  // SAME LIFELONG UID: an OUT record not with you while the same tool is present = a ghost (every ensure)
  java.util.ArrayList gh = new java.util.ArrayList();
  java.util.ArrayList to = new java.util.ArrayList();
  it = d.entries.values().iterator();
  while (it.hasNext()) {
    @PKG@.WdEntry e = (@PKG@.WdEntry) it.next();
    if (e.kind || e.in || e.raw != null || live.containsKey(e.eid)) continue;
    String lu = e.lu == null ? "" : e.lu;
    String t = lu.length() > 0 ? (String) keep.get(lu) : null;
    if (t == null || t.equals(e.eid)) continue;
    gh.add(e.eid);
    to.add(t);
  }
  int n = 0;
  if (gh.size() > 0 && llMerge(d, gh, to, false, "LIFELONG-TIDY", "")) { n = gh.size(); showCh = false; }
  // THE ONE-TIME PASS (per profile, marker llDone in index.json): the PLAIN tool records (no SkyyGear document) of a lifelong family that
  // existed when the marker was first absent, OUT and not with you, while that family's lifelong tool is present -> merged into it (Skyy's
  // 'Hatchet Crude'); History copy of the profile's files first, one requip.log line with the Undo. A profile born under 0.2.4 never runs it
  if (!d.llDone) {
    if (!d.exists) { d.llDone = true; return n; }
    java.util.ArrayList pg = new java.util.ArrayList();
    java.util.ArrayList pt = new java.util.ArrayList();
    it = d.entries.values().iterator();
    while (it.hasNext()) {
      @PKG@.WdEntry e = (@PKG@.WdEntry) it.next();
      boolean plain = !e.kind && !e.in && e.raw == null && !live.containsKey(e.eid);   // an OUT record, not with you
      if (e.lu != null && e.lu.length() > 0) plain = false;     // a lifelong tool (the same-uid rule handles those)
      if (e.rar != null && e.rar.length() > 0) plain = false;   // a SkyyGear document (rarity) = not a plain tool
      if (e.lv >= 0) plain = false;
      String t = plain ? (String) fam.get("f" + @PKG@.WdCodec.llFam(e.itemId())) : null;
      if (t != null && !t.equals(e.eid)) { pg.add(e.eid); pt.add(t); }
    }
    ONCE_RUNS = ONCE_RUNS + 1L;
    if (pg.size() == 0) {
      // nothing to merge: the marker rides on the next save (every Requip save writes index.json) - no extra write here, so a profile
      // that only looks at the page writes nothing; until that save the same (unchanged) records are simply checked again
      d.llDone = true;
      @PKG@.WdStore.log("LIFELONG-ONCE " + d.uuid + " " + d.key + " nothing to tidy (marker set, saved with the next change; lifelong families present " + fam.size() + ")");
      return n;
    }
    String hp = llHist(d);
    if (hp == null) return n;   // no History copy = nothing changes; the next ensure tries again
    if (llMerge(d, pg, pt, true, "LIFELONG-ONCE", " history=" + hp + " undo: with the server stopped, copy every file of " + hp + " back into requip/" + d.key + "/")) n = n + pg.size();
    return n;
  }
  if (showCh && !@PKG@.WdStore.save(d)) @PKG@.WdLog.warnOnce("tidyshow:" + d.key, "Requip " + d.key + ": the refreshed item names could not be saved (shown anyway)");
  return n;
}""")
# migration (once) + the crash repair of this profile, before anything else.''')
rep('''  return r;
}""")
M(ops, r"""
public static String save(@PKG@.WdData d, String okText) {''', '''  // 0.2.4: the lifelong tool records (a tier-up shows its new tier; old-tier ghosts merge into the tool you have) - not while busy / broken
  if (!d.bad && d.mig != 1 && !@PKG@.WdGate.busy(u)) {   // (after the journal repair above)
    try { tidyLL(d, cs); } catch (Throwable t) { @PKG@.WdLog.warnOnce("tidyll", "Requip: the lifelong tool tidy failed (nothing changed): " + t); }
  }
  return r;
}""")
M(ops, r"""
public static String save(@PKG@.WdData d, String okText) {''')

# 0.2.4: the per-profile run-once marker of the one-time lifelong tool pass (WdOps.tidyLL), saved in index.json
rep('"public Object ioLock;", "public int mig;", "public int ask01;",', '"public Object ioLock;", "public int mig;", "public int ask01;", "public boolean llDone;",')
rep('this.mig = 0; this.ask01 = -1; this.migrated = null;', 'this.mig = 0; this.ask01 = -1; this.llDone = false; this.migrated = null;')
rep('  doc.put("ask01", new org.bson.BsonInt32(d.ask01));\n  return doc;', '  doc.put("ask01", new org.bson.BsonInt32(d.ask01));\n  if (d.llDone) doc.put("llDone", new org.bson.BsonBoolean(true));   // 0.2.4: the one-time lifelong tool pass ran (0.2.3 ignores it)\n  return doc;')
rep('  d.ask01 = @PKG@.WdCodec.intOf(idx, "ask01", -1);\n  java.io.File[] fs = dir.toFile().listFiles();', '  d.ask01 = @PKG@.WdCodec.intOf(idx, "ask01", -1);\n  d.llDone = @PKG@.WdCodec.boolOf(idx, "llDone", false);   // 0.2.4\n  java.io.File[] fs = dir.toFile().listFiles();')
rep('    d.migrated = fresh.migrated; d.ask01 = fresh.ask01; d.exists = fresh.exists; d.mig = fresh.mig; d.dirty.clear();', '    d.migrated = fresh.migrated; d.ask01 = fresh.ask01; d.exists = fresh.exists; d.mig = fresh.mig; d.dirty.clear();\n    d.llDone = fresh.llDone;   // 0.2.4')
# ---------------------------------------------------------------------------------------------------------------- guards
assert s.count("registerCommand(") == REG0 and s.count("registerSystem(") == SYS0, "no new command or ECS system"
assert s.count(".put(\"wardrobe:") + s.count(".put(\"requip:") == BRPUT0, "no new bridge key published"
assert "this.rs < 6" not in s and "rs > 5" not in s and "rk < 6" not in s and "rs < 8" not in s, "every 0.2.3 six-slot bound moved to 14"
